                _ = &e;
                if ((e == error.Panic)) {
                    _ = Output.pretty("<magenta><b>panic</r> - {s} <i>({d}ms)</r>\n{s}", .{ (if (@typeInfo(@TypeOf(t)) == .@"enum" or @typeInfo(@TypeOf(t)) == .@"union") @tagName(t) else t.name), elapsed, @errorName(e) });
                    stats.panic = (stats.panic + 1);
                } else {
                    _ = Output.pretty("<red>fail</r> - {s} <i>({d}ms)</r>\n{s}", .{ (if (@typeInfo(@TypeOf(t)) == .@"enum" or @typeInfo(@TypeOf(t)) == .@"union") @tagName(t) else t.name), elapsed, @errorName(e) });
                    stats.fail = (stats.fail + 1);
                }
            } else {
                if ((memory_check == .leak)) {
                    _ = Output.pretty("<yellow>leak</r> - {s} <i>({d}ms)</r>\n", .{ name, elapsed });
                    stats.leak = (stats.leak + 1);
                } else {
                    _ = Output.pretty("<green>pass</r> - {s} <i>({d}ms)</r>\n", .{ name, elapsed });
                    stats.pass = (stats.pass + 1);
                }
            }
        }
        const total = stats.total();
        const total_time = stats.elapsed();
        if ((total == stats.pass)) {
            _ = Output.pretty("\n<green>All tests passed</r>\n", .{});
        } else {
            _ = Output.pretty("\n<green>{d}</r> passed", .{ stats.pass });
            if ((stats.fail > 0)) {
                _ = Output.pretty(", <red>{d}</r> failed", .{ stats.fail });
            } else {
                _ = Output.pretty(", 0 failed", .{});
            }
            if ((stats.leak > 0)) {
                _ = Output.pretty(", <yellow>{d}</r> leaked", .{ stats.leak });
            }
            if ((stats.panic > 0)) {
                _ = Output.pretty(", <magenta>{d}</r> panicked", .{ stats.panic });
            }
        }
        _ = Output.pretty("\n\tRan <b>{d}</r> tests in <b>{d}</r>ms\n\n", .{ total, total_time });
        return stats.exitCode();
}

pub fn extractName(t: TestFn) []const u8 {
        const seps: [2][]const u8 = .{ ".test.", ".decltest." };
        inline for (seps) |test_sep| {
            if (std.mem.lastIndexOf(u8, (if (@typeInfo(@TypeOf(t)) == .@"enum" or @typeInfo(@TypeOf(t)) == .@"union") @tagName(t) else t.name), test_sep)) |marker| {
                _ = &marker;
                const prefix = (if (@typeInfo(@TypeOf(t)) == .@"enum" or @typeInfo(@TypeOf(t)) == .@"union") @tagName(t) else t.name)[0..marker];
                const test_name = (if (@typeInfo(@TypeOf(t)) == .@"enum" or @typeInfo(@TypeOf(t)) == .@"union") @tagName(t) else t.name)[(marker + test_sep.len)..];
                const full_name = (blk_catch_4: { break :blk_catch_4 ((std.fmt.bufPrint(namebuf, "{s}\t{s}", .{ prefix, test_name })) catch |__ce_4| { _ = &__ce_4; @panic("name buffer too small"); }); });
                return full_name;
            }
        }
        return (if (@typeInfo(@TypeOf(t)) == .@"enum" or @typeInfo(@TypeOf(t)) == .@"union") @tagName(t) else t.name);
}

